<template><div class="cg"><div class="cg-banner"><div><h3>客户销量关系探索</h3><p>{{data?.period}} · 附件脱敏数据 · 仅展示所选对象的局部关系</p></div><span>{{data?.nodes.length||0}} 节点 / {{data?.edges.length||0}} 关系</span></div><div class="cg-search"><input v-model="query" placeholder="搜索客户名称、所在地、行业"><select v-model="province"><option value="">全部所在地</option><option v-for="p in provinces" :key="p">{{p}}</option></select><select v-model="industry"><option value="">全部行业</option><option v-for="i in industries" :key="i">{{i}}</option></select></div><div class="cg-layout"><aside class="cg-list"><small>匹配 {{matches.length}} 个客户</small><button v-for="c in matches.slice(0,60)" :key="c.id" :class="{on:chosen===c.id}" @click="chosen=c.id"><strong>{{c.name}}</strong><span>{{c.properties.所在地||'未标地区'}} · {{c.properties.行业类别||'未标行业'}}</span></button><p v-if="matches.length>60">仅列前60条，请缩小搜索范围。</p></aside><section v-if="customer" class="cg-content"><div class="cg-title"><h3>{{customer.name}}</h3><button @click="$emit('analyze','请分析客户'+customer.name+'在2025年的月度销量变化，并区分事实与事件影响推断。')">带入会话分析</button></div><div class="cg-meta"><span v-for="(v,k) in customer.properties" :key="k">{{k}}：{{v||'未提供'}}</span></div><h4>组织与业务关联 <small>当前展示 {{localNodes.length}} 个节点 / {{localLinks.length}} 条关系 · 悬浮查看属性</small></h4><div ref="graphEl" class="cg-network"></div><section v-if="selectedNode" class="cg-node-detail"><h4>{{selectedNode.name}} <small>{{selectedNode.type}}</small><button @click="selectedNode=null">收起</button></h4><div><span v-for="(value,key) in selectedNode.properties" :key="key">{{key}}：{{value||'未提供'}}</span></div></section><div class="cg-sales-head"><h4>月度实际销量</h4><b>累计 {{total.toLocaleString('zh-CN',{maximumFractionDigits:2})}} 立方米</b></div><div ref="salesEl" class="cg-trend"></div><details><summary>查看 {{sales.length}} 条原始月销量</summary><table><thead><tr><th>月份</th><th>销量（立方米）</th><th>数据来源</th></tr></thead><tbody><tr v-for="r in sales" :key="r.id"><td>{{r.properties.月份}}</td><td>{{Number(r.properties.数值).toLocaleString()}}</td><td>{{r.properties.数据来源}}</td></tr></tbody></table></details><p class="cg-warning">11月可能为部分月份；事件资料与此销量数据的时间范围不同，暂不生成事件导致销量变化的结论。</p></section><section v-else class="cg-empty">{{error||'请搜索并选择一个客户'}}</section></div></div></template>
<script setup>
import {ref,computed,onMounted,onBeforeUnmount,watch,nextTick} from 'vue'
import * as echarts from 'echarts'
import {graphTooltip,wrapGraphText} from './graphPresentation.js'
defineEmits(['analyze']);const selectedNode=ref(null);const data=ref(),query=ref(''),province=ref(''),industry=ref(''),chosen=ref(''),error=ref(''),graphEl=ref(),salesEl=ref();let graph,trend,observer
const customers=computed(()=>data.value?.nodes.filter(n=>n.type==='企业'&&n.properties.层级==='三级')||[])
const provinces=computed(()=>[...new Set(customers.value.map(n=>n.properties.所在地).filter(Boolean))].sort());const industries=computed(()=>[...new Set(customers.value.map(n=>n.properties.行业类别).filter(Boolean))].sort())
const matches=computed(()=>customers.value.filter(n=>(!province.value||n.properties.所在地===province.value)&&(!industry.value||n.properties.行业类别===industry.value)&&(n.name+Object.values(n.properties).join(' ')).includes(query.value.trim())))
const customer=computed(()=>customers.value.find(n=>n.id===chosen.value));const sales=computed(()=>data.value?.nodes.filter(n=>n.type==='指标值'&&n.properties.企业===customer.value?.name).sort((a,b)=>a.properties.月份.localeCompare(b.properties.月份))||[]);const total=computed(()=>sales.value.reduce((s,r)=>s+Number(r.properties.数值||0),0))
const nodeMap=computed(()=>new Map((data.value?.nodes||[]).map(n=>[n.id,n])))
const localLinks=computed(()=>(data.value?.edges||[]).filter(e=>(e.source===chosen.value||e.target===chosen.value)&&nodeMap.value.get(e.source)?.type!=='指标值'&&nodeMap.value.get(e.target)?.type!=='指标值'))
const localNodes=computed(()=>{if(!chosen.value)return [];const ids=new Set([chosen.value]);localLinks.value.forEach(e=>{ids.add(e.source);ids.add(e.target)});return [...ids].map(id=>nodeMap.value.get(id)).filter(Boolean)})
async function render(){await nextTick();if(!graphEl.value||!customer.value)return;selectedNode.value=null;graph?.dispose();trend?.dispose();graph=echarts.init(graphEl.value);trend=echarts.init(salesEl.value);
graph.setOption({tooltip:graphTooltip(p=>{if(p.dataType==='edge')return `${nodeMap.value.get(p.data.source)?.name} → ${nodeMap.value.get(p.data.target)?.name}\n关系：${p.data.value}\n${wrapGraphText(p.data.properties?.说明)}`;const n=nodeMap.value.get(p.data.id);return `${n.name}\n类型：${n.type}\n${Object.entries(n.properties).map(([k,v])=>wrapGraphText(k+'：'+(v||'未提供'))).join('\n')}`}),series:[{type:'graph',layout:'force',force:{initLayout:'circular',repulsion:850,edgeLength:155,gravity:.1,layoutAnimation:false},roam:true,draggable:true,scaleLimit:{min:.5,max:3},edgeSymbol:['none','arrow'],edgeSymbolSize:[0,9],lineStyle:{color:'#6d82a0',width:2,curveness:.08},edgeLabel:{show:false,formatter:'{c}',fontSize:11,color:'#405a7c',backgroundColor:'#ffffffdd',padding:3},data:localNodes.value.map(n=>({id:n.id,name:n.name,symbol:'circle',symbolSize:n.id===chosen.value?52:42,itemStyle:{color:n.id===chosen.value?'#2557c5':n.type==='企业'?'#7538af':n.type==='地点'?'#007d81':'#b36508',borderColor:'#fff',borderWidth:3},label:{show:false,position:'bottom',distance:9,color:'#233b5a',fontSize:12,fontWeight:600,backgroundColor:'#ffffffee',padding:4,width:140,overflow:'break'}})),links:localLinks.value.map(e=>({...e,value:e.type})),labelLayout:{hideOverlap:true},emphasis:{focus:'adjacency'}}]});graph.on('click',p=>{if(p.dataType==='node')selectedNode.value=nodeMap.value.get(p.data.id)});
trend.setOption({tooltip:{trigger:'axis'},grid:{left:65,right:20,top:20,bottom:35},xAxis:{type:'category',data:sales.value.map(n=>n.properties.月份),axisLabel:{fontSize:10,color:'#8999af'},axisLine:{lineStyle:{color:'#e4eaf2'}}},yAxis:{type:'value',axisLabel:{fontSize:10,color:'#8999af'},splitLine:{lineStyle:{color:'#f0f3f8'}}},series:[{name:'月销量（立方米）',type:'bar',barMaxWidth:26,data:sales.value.map(n=>Number(n.properties.数值)),itemStyle:{color:'#7b9edb',borderRadius:[4,4,0,0]}}]})}
onMounted(async()=>{try{const r=await fetch('/customer-graph.json');if(!r.ok)throw Error();data.value=await r.json();chosen.value=customers.value[0]?.id||'';observer=new ResizeObserver(()=>{graph?.resize();trend?.resize()});observer.observe(graphEl.value.parentElement)}catch{error.value='数据加载失败，请刷新重试'}});watch(chosen,render);onBeforeUnmount(()=>{observer?.disconnect();graph?.dispose();trend?.dispose()})
</script>
<style scoped>
.cg-banner{display:flex;align-items:center;justify-content:space-between;margin:20px 0}.cg h3{font-size:16px;color:#4c5f7a}.cg-banner p,.cg-banner>span{font-size:11px;color:#99a7b9;margin-top:8px}.cg-search{display:flex;gap:10px;margin:20px 0}.cg-search input{flex:1;min-width:0}.cg-search input,.cg-search select{border:1px solid #dce4ef;background:white;border-radius:7px;padding:10px;font-size:12px;color:#7f91aa}.cg-layout{display:grid;grid-template-columns:215px minmax(0,1fr);border:1px solid #e1e8f2;border-radius:12px;overflow:hidden}.cg-list{padding:15px;background:#fafcfe;border-right:1px solid #e2e9f2;max-height:800px;overflow:auto}.cg-list>small{color:#9eabbd;font-size:10px}.cg-list button{width:100%;text-align:left;padding:12px 10px;margin-top:5px;border-radius:7px}.cg-list button.on{background:#edf3ff}.cg-list strong{font-size:12px;color:#637a9b;display:block}.cg-list span{display:block;font-size:10px;color:#a0adbe;margin-top:6px}.cg-content{padding:22px;min-width:0}.cg-title,.cg-sales-head{display:flex;align-items:center;justify-content:space-between;gap:15px}.cg-title button{font-size:11px;color:#7190bf}.cg-meta{display:flex;flex-wrap:wrap;gap:8px;margin:15px 0 24px}.cg-meta span{font-size:10px;background:#f4f7fb;padding:5px 8px;color:#8d9eb6;border-radius:4px}.cg h4{font-size:12px;color:#7187a5}.cg h4 small{font-size:10px;color:#adb7c6;font-weight:400;margin-left:9px}.cg-network{height:290px;background:#fcfdff;border:1px solid #edf1f7;border-radius:9px;margin:13px 0 25px}.cg-trend{height:220px}.cg-sales-head b{font-size:11px;color:#7f98bb}.cg details{font-size:11px;color:#8c9fb9}.cg table{width:100%;margin:12px 0}.cg th{background:#f3f6fb;color:#7c8faa}.cg td{border-color:#e6edf6;color:#7c8faa}.cg-warning,.cg-list>p{font-size:10px;color:#ac9b7f;line-height:1.8;margin-top:17px}.cg-empty{padding:50px;color:#9ca9bb}@media(max-width:900px){.cg-layout{grid-template-columns:160px 1fr}.cg-banner>span{display:none}.cg-search{flex-wrap:wrap}.cg-search input{flex-basis:100%}}
.cg-network{height:360px;background:#f6f9fe;border-color:#d9e3f1}.cg h3{color:#213854}.cg-list strong{color:#344e72}.cg-list span,.cg-banner p,.cg-meta span{color:#64758e}.cg h4,.cg-sales-head b{color:#3f587b}.cg-node-detail{border:1px solid #dbe5f2;border-radius:8px;background:#f7faff;padding:14px;margin-bottom:22px}.cg-node-detail h4{display:flex;align-items:center;gap:8px}.cg-node-detail button{margin-left:auto;color:#647f9f;font-size:11px}.cg-node-detail>div{display:flex;gap:9px;flex-wrap:wrap;margin-top:12px}.cg-node-detail span{font-size:11px;color:#4b607d}
</style>
